CREATE TABLE "system_logs" ("id" varchar PRIMARY KEY NOT NULL, "eventType" varchar CHECK( "eventType" IN ('server_started','server_stopped','server_restarted','server_crashed','server_timeout','server_created','server_updated','server_deleted','server_config_changed','connection_established','connection_lost','connection_retry','connection_failed','health_check_passed','health_check_failed','system_startup','system_shutdown','system_error') ) NOT NULL, "message" varchar(500), "description" text, "level" varchar CHECK( "level" IN ('debug','info','warning','error','critical') ) NOT NULL DEFAULT ('info'), "status" varchar CHECK( "status" IN ('success','failed','in_progress','cancelled') ) NOT NULL DEFAULT ('success'), "serverId" varchar(36), "serverName" varchar(255), "serverVersion" varchar(100), "serverPort" integer, "userId" varchar(36), "source" varchar(255), "context" text, "metadata" text, "createdAt" datetime NOT NULL DEFAULT (datetime('now')), CONSTRAINT "FK_af8bc5ddf6bb239c2b40173a78b" FOREIGN KEY ("serverId") REFERENCES "mcp_servers" ("id") ON DELETE CASCADE ON UPDATE NO ACTION, CONSTRAINT "FK_f4f5248b93c3ca62ed3761b30f1" FOREIGN KEY ("userId") REFERENCES "users" ("id") ON DELETE SET NULL ON UPDATE NO ACTION);
CREATE TABLE "user_roles" ("userId" varchar NOT NULL, "roleId" varchar NOT NULL, CONSTRAINT "FK_472b25323af01488f1f66a06b67" FOREIGN KEY ("userId") REFERENCES "users" ("id") ON DELETE CASCADE ON UPDATE CASCADE, CONSTRAINT "FK_86033897c009fcca8b6505d6be2" FOREIGN KEY ("roleId") REFERENCES "roles" ("id") ON DELETE NO ACTION ON UPDATE NO ACTION, PRIMARY KEY ("userId", "roleId"));
CREATE TABLE "users" ("id" varchar PRIMARY KEY NOT NULL, "username" varchar(100) NOT NULL, "email" varchar(255) NOT NULL, "password" varchar(255) NOT NULL, "firstName" varchar(100), "lastName" varchar(100), "status" varchar CHECK( "status" IN ('active','inactive','suspended','pending') ) NOT NULL DEFAULT ('pending'), "emailVerified" boolean NOT NULL DEFAULT (0), "emailVerificationToken" varchar(255), "passwordResetToken" varchar(255), "passwordResetExpires" datetime, "lastLoginAt" datetime, "lastLoginIp" varchar(45), "loginAttempts" integer NOT NULL DEFAULT (0), "lockedUntil" datetime, "preferences" text, "metadata" text, "createdAt" datetime NOT NULL DEFAULT (datetime('now')), "updatedAt" datetime NOT NULL DEFAULT (datetime('now')), CONSTRAINT "UQ_fe0bb3f6520ee0469504521e710" UNIQUE ("username"), CONSTRAINT "UQ_97672ac88f789774dd47f7c8be3" UNIQUE ("email"));
